#!/usr/bin/env python3
"""The versions a host restores for the FDW packages: one generated file, adopted deliberately.

  hostprops.py generate --manifest FILE --out FILE
  hostprops.py adopt --props FILE (--from FILE | --bundle-id ID --bundle VERSION) [--dry-run] [--json]

generate  writes Fdw.PackageVersions.props from a release manifest (the one bundle.py builds the bundle from):
          one <PackageVersion> per package, in two groups chosen by FDW_TIER.
            release            the exact version of the manifest, [x.y.z]
            internal, develop  the LINE of the bundle as a float, <major>.<minor>.*-<tier>.*, the same for every package
          DECIDED (Release-Supervisor, FDW-4784 step D, 2026-11-10): the development tiers float on the line, not on each package's
          own major. FDW's internal and develop builds get ONE number from the line (tail.py), so once a package has gone to 2.0.0 while
          the line is 1.5 its internal builds read 1.5.7-internal.*, and after the line moves to 2.0 every package's reads
          2.0.1-internal.*: a per-package major float would find nothing in one case or the other. A 1.x package carrying a 2.0.x
          internal number on dev is accepted. Releases stay per package: the release group is exact, adopted one package at a time
          by its owner, and a development float never brings a new major to a release. The line moves with `version-bump` to the
          bundle's line right after each release. The bundle carries the file at fdw/Fdw.PackageVersions.props.

adopt     takes such a file (from a file, or from the bundle package on nuget.org), compares its release group with the one the
          host holds, prints one row per package that moved with its level, and writes the file into the host. A MAJOR row is
          marked BREAKING: the host's owner decides to take it, which is the only way a new major reaches a host. The host
          takes the whole file, not a part: a dependent of a package that went major was rebuilt against it and needs it.
          --dry-run prints the table and writes nothing. The first time, a host replaces its own Fdw.* lines with
          <Import Project="Fdw.PackageVersions.props" /> in its Directory.Packages.props, and every row is "added".

Nothing here is assumed: a manifest that is not a valid bundle manifest, a file with no release group, or a bundle without the file
stops the run and says why.
"""
import argparse
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from xml.sax.saxutils import quoteattr

import bundle
from feeds import NugetOrg

FILE_IN_BUNDLE = "fdw/Fdw.PackageVersions.props"
RELEASE_CONDITION = "'$(FDW_TIER)' == 'release'"
DEV_CONDITION = "'$(FDW_TIER)' == 'internal' Or '$(FDW_TIER)' == 'develop'"
VERSION = re.compile(r"^(\d+)\.(\d+)\.(\d+)(?:-(.+))?$")


class HostPropsError(Exception):
    pass


def render(manifest):
    """The text of Fdw.PackageVersions.props for a release manifest. Packages are sorted by id, so the same manifest gives the same bytes."""
    problems = bundle.check(manifest)
    if problems:
        raise HostPropsError("the manifest is not a valid bundle manifest: " + "; ".join(problems))
    items = sorted(manifest["packages"].items(), key=lambda kv: kv[0].lower())
    release = "\n".join(f"    <PackageVersion Include={quoteattr(pid)} Version=\"[{v}]\" />" for pid, v in items)
    line = ".".join(manifest["version"].split("-")[0].split(".")[:2])
    dev = "\n".join(f"    <PackageVersion Include={quoteattr(pid)} Version=\"{line}.*-$(FDW_TIER).*\" />" for pid, v in items)
    return f"""<Project>
  <!-- Generated by public/tools/versioning/hostprops.py from the release manifest of {manifest['id']} {manifest['version']}. Do not edit.
       release: the exact version of the release. internal and develop: a float on the line of the bundle ({line}), the same for every
       package, because development builds carry one number from the line. A new major reaches a release only when its owner adopts
       this file again. -->
  <ItemGroup Condition="{RELEASE_CONDITION}">
{release}
  </ItemGroup>
  <ItemGroup Condition="{DEV_CONDITION}">
{dev}
  </ItemGroup>
</Project>
"""


def read_release(text, origin="props"):
    """{package id: exact version} from the release group of a Fdw.PackageVersions.props."""
    try:
        root = ET.fromstring(text.lstrip("﻿"))
    except ET.ParseError as e:
        raise HostPropsError(f"{origin} is not XML: {e}")
    for group in root.findall("ItemGroup"):
        if group.get("Condition") == RELEASE_CONDITION:
            return {item.get("Include"): item.get("Version", "").strip("[]") for item in group.findall("PackageVersion")}
    raise HostPropsError(f"{origin} has no ItemGroup with Condition {RELEASE_CONDITION}")


def level(old, new):
    """patch, minor or major for a move between two exact versions; 'changed' when only the tail differs or a version is not plain."""
    a, b = VERSION.match(old), VERSION.match(new)
    if not a or not b:
        return "changed"
    for name, x, y in zip(("major", "minor", "patch"), a.groups()[:3], b.groups()[:3]):
        if x != y:
            return name
    return "changed"


def rows(old, new):
    """One row per package that moved: (package id, old version or None, new version or None, level), most severe first."""
    found = []
    for pid in sorted(set(old) | set(new), key=str.lower):
        if pid not in old:
            found.append((pid, None, new[pid], "added"))
        elif pid not in new:
            found.append((pid, old[pid], None, "removed"))
        elif old[pid] != new[pid]:
            found.append((pid, old[pid], new[pid], level(old[pid], new[pid])))
    order = {"major": 0, "removed": 1, "minor": 2, "patch": 3, "changed": 4, "added": 5}
    return sorted(found, key=lambda r: (order[r[3]], r[0].lower()))


def summary(found):
    counts = {}
    for _, _, _, name in found:
        counts[name] = counts.get(name, 0) + 1
    if not found:
        return "no package moved"
    return f"{len(found)} package(s) moved: " + ", ".join(f"{n} {k}" for k, n in sorted(counts.items(), key=lambda kv: kv[0]))


def table(found):
    lines = []
    for pid, old, new, name in found:
        mark = "  BREAKING" if name in ("major", "removed") else ""
        lines.append(f"  {name.upper():8s} {pid}  {old or '-'} -> {new or '-'}{mark}")
    return lines


def bundle_file(bundle_id, version):
    text = NugetOrg().held_file(bundle_id, version, FILE_IN_BUNDLE)
    if text is None:
        raise HostPropsError(f"{bundle_id} {version} is not on nuget.org or does not carry {FILE_IN_BUNDLE}")
    return text


def read_text(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def adopt(props_path, new_text, dry_run):
    """The rows for adopting `new_text` into the host file at `props_path`; writes the file unless dry_run."""
    new = read_release(new_text, "the file to adopt")
    old = {}
    if os.path.exists(props_path):
        with open(props_path, encoding="utf-8") as f:
            old = read_release(f.read(), props_path)
    found = rows(old, new)
    if not dry_run:
        with open(props_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(new_text)
    return found


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    g = sub.add_parser("generate")
    g.add_argument("--manifest", required=True)
    g.add_argument("--out", required=True)
    a_ = sub.add_parser("adopt")
    a_.add_argument("--props", required=True)
    a_.add_argument("--from", dest="source")
    a_.add_argument("--bundle-id")
    a_.add_argument("--bundle")
    a_.add_argument("--dry-run", action="store_true")
    a_.add_argument("--json", action="store_true")
    a = ap.parse_args(argv)
    try:
        if a.cmd == "generate":
            with open(a.manifest, encoding="utf-8") as f:
                text = render(json.load(f))
            with open(a.out, "w", encoding="utf-8", newline="\n") as f:
                f.write(text)
            return
        from_bundle = bool(a.bundle_id) or bool(a.bundle)
        if bool(a.source) == from_bundle or (from_bundle and not (a.bundle_id and a.bundle)):
            ap.error("give --from FILE, or --bundle-id and --bundle together")
        found = adopt(a.props, bundle_file(a.bundle_id, a.bundle) if from_bundle else read_text(a.source), a.dry_run)
    except (HostPropsError, OSError, ValueError) as e:
        sys.exit(f"FAIL: {e}")
    if a.json:
        print(json.dumps({"summary": summary(found), "rows": [dict(zip(("package", "old", "new", "level"), r)) for r in found]}, indent=1))
    else:
        print(summary(found) + (" (dry run, nothing written)" if a.dry_run else f"; written to {a.props}"))
        print("\n".join(table(found)))


if __name__ == "__main__":
    main()
